
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_rscan_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_rscan", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.885377693024512e+00, -4.786537902748705e+00, -4.648004553424052e+00, -4.456027038044825e+00, -4.194272345098779e+00, -3.845535655804800e+00, -3.395785714906000e+00, -2.841212272027905e+00, -2.198877440573860e+00, -1.505826632661682e+00, -8.553589055458800e-01, -6.231284977518260e-01, -6.330851171089192e-01, -5.324915028716907e-01, -3.632417648237700e-01, -1.986460738481111e-01, -8.497739425390488e-02, -2.619830233249333e-02, -3.726122618398707e-03, -1.739992820320003e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


